#!/usr/bin/env python3
from __future__ import annotations

import json
import os
import shutil
import sqlite3
import subprocess
from datetime import datetime, timezone
from pathlib import Path

ROOT = Path(os.environ.get('EDARSAHUB_ROOT', '/app')).resolve()
GIT = ROOT / '.git'
QUEUE = GIT / 'universal-worker-queue'
GUARD_STATE = GIT / 'agent-guard' / 'state'
TARGETS = (
    'worker-p1-result-publisher-idempotency-20260827',
    'worker-worker-canonical-python-runtime-20260826',
    'worker-worker-concurrent-producer-branches-v1-20260827',
)


def run(args):
    return subprocess.run(args, cwd=ROOT, text=True, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, check=False)


def active(job_id):
    return any((QUEUE / d / f'{job_id}.json').exists() for d in ('pending', 'processing'))


def process_alive(job_id):
    proc = Path('/proc')
    if not proc.is_dir():
        return False
    for entry in proc.iterdir():
        if not entry.name.isdigit():
            continue
        try:
            text = (entry / 'cmdline').read_bytes().replace(b'\x00', b' ').decode('utf-8', 'ignore')
        except OSError:
            continue
        if job_id in text:
            return True
    return False


def worktrees():
    result = run(['git', 'worktree', 'list', '--porcelain'])
    if result.returncode != 0:
        raise RuntimeError('WORKTREE_LIST_FAILED:' + result.stdout[-1000:])
    items, current = [], {}
    for line in result.stdout.splitlines() + ['']:
        if not line:
            if current:
                items.append(current)
                current = {}
            continue
        key, _, value = line.partition(' ')
        current[key] = value
    return items


def is_sqlite(path: Path) -> bool:
    try:
        with path.open('rb') as handle:
            return handle.read(16) == b'SQLite format 3\x00'
    except OSError:
        return False


def clean_sqlite(path: Path, job_id: str, evidence: list[str]) -> None:
    connection = sqlite3.connect(str(path))
    try:
        tables = [row[0] for row in connection.execute("SELECT name FROM sqlite_master WHERE type='table'")]
        for table in tables:
            columns = list(connection.execute(f'PRAGMA table_info(\"{table}\")'))
            text_columns = [row[1] for row in columns if str(row[2]).upper() in ('TEXT', '', 'VARCHAR')]
            for column in text_columns:
                query = f'SELECT rowid FROM \"{table}\" WHERE \"{column}\" = ?'
                rows = [row[0] for row in connection.execute(query, (job_id,))]
                if not rows:
                    continue
                placeholders = ','.join('?' for _ in rows)
                connection.execute(f'DELETE FROM \"{table}\" WHERE rowid IN ({placeholders})', rows)
                evidence.append(f'sqlite_rows_deleted:{path}:{table}:{column}:{len(rows)}')
        connection.commit()
    finally:
        connection.close()


def reconcile(apply=True):
    stamp = datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')
    quarantine = GUARD_STATE / 'orphaned' / stamp
    report = {'schema': 'edarsahub.agent-guard-orphan-reconcile.v2', 'generated_at_utc': stamp, 'targets': {}}
    listed_worktrees = worktrees()
    for job_id in TARGETS:
        if active(job_id) or process_alive(job_id):
            raise RuntimeError(f'FAIL_CLOSED_ACTIVE_OWNER:{job_id}')
        actions = []
        for item in listed_worktrees:
            directory = item.get('worktree', '')
            branch = item.get('branch', '')
            if job_id in directory or job_id in branch:
                if Path(directory).resolve() == ROOT:
                    raise RuntimeError(f'REFUSE_MAIN_WORKTREE:{job_id}')
                if apply:
                    removed = run(['git', 'worktree', 'remove', '--force', directory])
                    if removed.returncode != 0:
                        raise RuntimeError(f'WORKTREE_REMOVE_FAILED:{job_id}:{removed.stdout[-500:]}')
                actions.append('worktree_removed:' + directory)
        for branch in (f'agent/worker/{job_id}', f'agent/{job_id}'):
            if run(['git', 'show-ref', '--verify', '--quiet', f'refs/heads/{branch}']).returncode == 0:
                if apply:
                    deleted = run(['git', 'branch', '-D', branch])
                    if deleted.returncode != 0:
                        raise RuntimeError(f'BRANCH_DELETE_FAILED:{job_id}:{deleted.stdout[-500:]}')
                actions.append('branch_deleted:' + branch)
        if GUARD_STATE.is_dir():
            for path in sorted(GUARD_STATE.rglob('*')):
                if not path.is_file() or '/orphaned/' in str(path):
                    continue
                if is_sqlite(path):
                    if apply:
                        clean_sqlite(path, job_id, actions)
                    continue
                try:
                    raw = path.read_bytes()
                except OSError:
                    continue
                if job_id.encode() not in raw and job_id not in path.name:
                    continue
                relative = path.relative_to(GUARD_STATE)
                target = quarantine / relative
                if apply:
                    target.parent.mkdir(parents=True, exist_ok=True)
                    shutil.move(str(path), str(target))
                actions.append('state_quarantined:' + str(relative))
        report['targets'][job_id] = {'active': False, 'process_alive': False, 'actions': actions}
    if apply:
        run(['git', 'worktree', 'prune'])
    return report


if __name__ == '__main__':
    print(json.dumps(reconcile(True), ensure_ascii=False, indent=2))
